	pipeR         *pipe.PipeReader
	pipeW         *pipe.PipeWriter
	writeDeadline pipe.PipeDeadline

	dieOnce         sync.Once
	dieHook         func()
	dieErr          error
	stateLock       sync.RWMutex
	connectDone     chan struct{}
	connectOnce     sync.Once
	connectErr      error
	connectDeadline pipe.PipeDeadline

	reportOnce sync.Once
}

// newStream initiates a Stream struct
func newStream(id uint32, sess *Session) *Stream {
	s := new(Stream)
	s.id = id
	s.sess = sess
	s.pipeR, s.pipeW = pipe.Pipe()
	s.writeDeadline = pipe.MakePipeDeadline()
	s.connectDeadline = pipe.MakePipeDeadline()
	s.connectDone = make(chan struct{})
	return s
}

// Read implements net.Conn
func (s *Stream) Read(b []byte) (n int, err error) {
	n, err = s.pipeR.Read(b)
	s.stateLock.RLock()
	defer s.stateLock.RUnlock()
	if n == 0 && s.dieErr != nil {
		err = s.dieErr
	}
	return
}

