func (s *Stream) Write(b []byte) (n int, err error) {
	select {
	case <-s.writeDeadline.Wait():
		return 0, os.ErrDeadlineExceeded
	default:
	}
	s.stateLock.RLock()
	dieErr := s.dieErr
	s.stateLock.RUnlock()
	if dieErr != nil {
		return 0, dieErr
	}
	n, err = s.sess.writeDataFrame(s.id, b)
	return
}

