	var once bool
	s.dieOnce.Do(func() {
		s.stateLock.Lock()
		s.dieErr = net.ErrClosed
		s.stateLock.Unlock()
		s.completeConnect(net.ErrClosed)
		s.pipeR.Close()
		once = true
	})
	if once {
